Method.Source:
public void insert()
{
    this.AVAPrinterCode = this.avaGetCurrentUserPrinterCode();

    next insert();
}

private AVAPrinterCode avaGetCurrentUserPrinterCode()
{
    WHSWorkUserSession  avaWHSUserSession;

    avaWHSUserSession = WHSWorkUserSession::find(this.UserId);

    return avaWHSUserSession.AVAPrinterCode;
}
